# A fixed-capacity least-recently-used cache.
#
# Relies on Ruby's Hash preserving insertion order: the first key is always
# the least recently used, and re-inserting a key moves it to the end.
class LRUCache
  def initialize(capacity)
    raise ArgumentError, "capacity must be a positive integer" unless capacity.is_a?(Integer) && capacity.positive?

    @capacity = capacity
    @store = {}
  end

  # Returns the value for key (marking it most recently used), or nil if absent.
  def get(key)
    return nil unless @store.key?(key)

    value = @store.delete(key)
    @store[key] = value
  end
  alias [] get

  # Stores value under key, evicting the least recently used entry if full.
  def set(key, value)
    @store.delete(key)
    @store[key] = value
    @store.shift if @store.size > @capacity
    value
  end
  alias []= set

  def key?(key)
    @store.key?(key)
  end

  def delete(key)
    @store.delete(key)
  end

  def size
    @store.size
  end

  def clear
    @store.clear
  end
end
